// Author: MiYu. Source active item abilities consume charges/cooldowns and change health, mana or illusion instances.
#include "session.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <sstream>

namespace war3 {
namespace {
float number(jass::Real v){return std::bit_cast<float>(v.bits());}
jass::Real real(float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));}
std::vector<std::uint32_t> abilities(ObjectData& data,std::uint32_t item){std::vector<std::uint32_t> ids;std::stringstream input(data.field(item,"ItemData","abilList"));std::string part;while(std::getline(input,part,',')){auto first=part.find_first_not_of(" \t");if(first==std::string::npos)continue;part=part.substr(first,part.find_last_not_of(" \t")-first+1);if(part.size()==4)ids.push_back(ObjectData::code(part));if(ids.size()>256)throw std::runtime_error("Item ability list exceeds budget");}return ids;}
}
void ScriptSession::removeItem(std::uint32_t handle) {if(!alive(handle,NativeKind::Item))return;auto state=items_.at(handle);if(alive(state->holder,NativeKind::Unit))for(auto& slot:units_.at(state->holder)->inventory)if(slot==handle)slot=0;items_.erase(handle);destroy(runtime_.handle("item",handle),NativeKind::Item);}
bool ScriptSession::itemNeedsTarget(std::uint32_t handle) {if(!alive(handle,NativeKind::Item))return false;for(auto id:abilities(definitions(),items_.at(handle)->type))if(definitions().field(id,"AbilityData","code")=="AIil")return true;return false;}
double ScriptSession::itemCooldown(std::uint32_t unitId,std::uint32_t itemId) {if(!alive(unitId,NativeKind::Unit) || !alive(itemId,NativeKind::Item))return 0;auto u=units_.at(unitId);auto item=items_.at(itemId);auto entries=abilities(definitions(),item->type);if(entries.empty())return 0;auto group=definitions().field(item->type,"ItemData","cooldownID",ObjectData::name(entries.front()));auto found=u->itemCooldowns.find(group);return found==u->itemCooldowns.end()?0:std::max(0.,found->second-simulationTime_);}
bool ScriptSession::useItem(std::uint32_t handle,std::uint32_t itemId,std::uint32_t target) {
    if(!alive(handle,NativeKind::Unit) || !alive(itemId,NativeKind::Item))return false;auto user=units_.at(handle);auto held=items_.at(itemId);if(user->illusion || user->removing || user->paused || number(user->life)<=0 || held->holder!=handle)return false;auto& data=definitions();if(data.number(held->type,"ItemData","usable")==0)return false;auto entries=abilities(data,held->type);if(entries.empty())return false;if(entries.size()!=1)throw std::runtime_error("Compound active item abilities are not implemented: "+ObjectData::name(held->type));auto ability=entries.front();if(!data.ability(ability))throw std::runtime_error("Missing item ability: "+ObjectData::name(ability));auto kind=data.field(ability,"AbilityData","code");if(kind!="AIil" && kind!="AIhe" && kind!="AIma" && kind!="AIre")throw std::runtime_error("Active item ability is not implemented: "+kind);auto group=data.field(held->type,"ItemData","cooldownID",ObjectData::name(ability));auto cooldown=user->itemCooldowns.find(group);if(cooldown!=user->itemCooldowns.end() && cooldown->second>simulationTime_)return false;bool perishable=data.number(held->type,"ItemData","perishable")!=0;if(perishable && held->charges<=0)return false;
    auto destination=target?target:handle;if(!alive(destination,NativeKind::Unit))return false;auto affected=units_.at(destination);if(affected->removing || number(affected->life)<=0 || (destination!=handle && affected->owner!=user->owner && !(config_.players[user->owner].alliances[affected->owner]&1)))return false;auto range=data.number(ability,"AbilityData","Rng1");if(range>0 && std::hypot(number(affected->x)-number(user->x),number(affected->y)-number(user->y))>range+user->collision+affected->collision)return false;float amount=data.number(ability,"AbilityData","DataA1"),second=data.number(ability,"AbilityData","DataB1"),duration=data.number(ability,"AbilityData",affected->hero?"HeroDur1":"Dur1"),delay=data.number(ability,"AbilityData","Cool1");float cost=data.number(ability,"AbilityData","Cost1");if(number(user->mana)<cost)return false;if(cost<0 || delay<0 || duration<0 || amount<0 || second<0)throw std::runtime_error("Negative active item parameters");
    if(kind=="AIil"){if(affected->building || affected->illusion || !spawnPoint(*affected,affected->type))return false;}else{if(destination!=handle)return false;bool health=(kind=="AIhe" || kind=="AIre") && number(user->life)<number(user->maxLife),mana=(kind=="AIma" || kind=="AIre") && number(user->mana)<number(user->maxMana);if(!health && !mana)return false;}
    user->mana=real(number(user->mana)-cost);if(held->charges>0)--held->charges;user->itemCooldowns[group]=simulationTime_+delay;if(kind=="AIil")illusions(handle,destination,1,amount,second,duration,ObjectData::code("BIil"));else{if(kind=="AIhe" || kind=="AIre")unitLife(runtime_.handle("unit",handle),real(number(user->life)+amount));if(alive(handle,NativeKind::Unit) && (kind=="AIma" || kind=="AIre"))user->mana=real(std::min(number(user->maxMana),number(user->mana)+(kind=="AIma"?amount:second)));}ScriptContext context;context.manipulatedItem=itemId;unitEvent(handle,50,87,context);if(perishable && alive(itemId,NativeKind::Item) && held->charges==0)removeItem(itemId);return true;
}
}
